import 'package:audioplayers/audioplayers.dart';

enum AlertKind { call, videoCall, message, file }

/// Original app-specific PCM melodies, generated by tool/generate_assets.py.
/// Playback errors cannot break chat, transfer or WebRTC signaling.
class Alerts {
  AudioPlayer? _ringer;
  final AudioPlayer _effect = AudioPlayer();
  bool enabled = true;

  String _asset(AlertKind kind) => switch (kind) {
    AlertKind.call => 'sounds/call.wav',
    AlertKind.videoCall => 'sounds/video_call.wav',
    AlertKind.message => 'sounds/message.wav',
    AlertKind.file => 'sounds/file.wav',
  };

  Future<void> ring(AlertKind kind) async {
    if (!enabled) return;
    await stopRing();
    try {
      final player = AudioPlayer();
      _ringer = player;
      await player.setReleaseMode(ReleaseMode.loop);
      await player.play(AssetSource(_asset(kind)));
    } catch (_) {/* Device may have no audio output. */}
  }

  Future<void> stopRing() async {
    final player = _ringer;
    _ringer = null;
    if (player == null) return;
    try { await player.stop(); await player.dispose(); } catch (_) {}
  }

  Future<void> notify(AlertKind kind) async {
    if (!enabled) return;
    try {
      await _effect.stop();
      await _effect.play(AssetSource(_asset(kind)));
    } catch (_) {}
  }

  Future<void> dispose() async {
    await stopRing();
    await _effect.dispose();
  }
}